#if swift(>=5.8)
@_documentation(visibility: private)
#endif
@available(macOS 10.15, *)
public struct FfiConverterTypeWalletClient: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = WalletClient

    public static func lift(_ handle: UInt64) throws -> WalletClient {
        return WalletClient(unsafeFromHandle: handle)
    }

    public static func lower(_ value: WalletClient) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> WalletClient {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: WalletClient, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


