// Put the implementation in a struct so we don't pollute the top-level namespace
@available(macOS 10.15, *)
fileprivate struct UniffiCallbackInterfaceWalletHttpHost {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceWalletHttpHost = UniffiVTableCallbackInterfaceWalletHttpHost(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeWalletHttpHost.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface WalletHttpHost: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeWalletHttpHost.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface WalletHttpHost: handle missing in uniffiClone")
            }
        },
        executeHttp: { (
            uniffiHandle: UInt64,
            request: RustBuffer,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteRustBuffer,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall: @Sendable () async throws -> HttpResponse = {
                () async throws -> HttpResponse in
                guard let uniffiObj = try? FfiConverterTypeWalletHttpHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try await uniffiObj.executeHttp(
                     request: try FfiConverterTypeHttpRequest_lift(request)
                )
            }

            let uniffiHandleSuccess: @Sendable (HttpResponse) -> Void = { (returnValue: HttpResponse) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: FfiConverterTypeHttpResponse_lower(returnValue),
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError: @Sendable (Int8, RustBuffer) -> Void = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: RustBuffer.empty(),
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsyncWithError(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                lowerError: FfiConverterTypeHttpHostError_lower,
                droppedCallback: uniffiOutDroppedCallback
            )
        },
        cancelHttp: { (
            uniffiHandle: UInt64,
            requestId: RustBuffer,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteVoid,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall: @Sendable () async throws -> () = {
                () async throws -> () in
                guard let uniffiObj = try? FfiConverterTypeWalletHttpHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return await uniffiObj.cancelHttp(
                     requestId: try FfiConverterTypeHttpRequestId_lift(requestId)
                )
            }

            let uniffiHandleSuccess: @Sendable (()) -> Void = { (returnValue: ()) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultVoid(
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError: @Sendable (Int8, RustBuffer) -> Void = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultVoid(
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsync(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                droppedCallback: uniffiOutDroppedCallback
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
